package cn.workbench;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.mock.web.MockHttpServletRequest;import java.util.*;import java.util.concurrent.*;import java.time.*;import static org.assertj.core.api.Assertions.*;import static cn.workbench.Records.map;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:workflow;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","task.bootstrap-password=TestOnly-Synthetic12345","task.totp-key=AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8="}) @org.springframework.test.context.TestExecutionListeners(value={org.springframework.test.context.support.DependencyInjectionTestExecutionListener.class,org.springframework.test.context.transaction.TransactionalTestExecutionListener.class},mergeMode=org.springframework.test.context.TestExecutionListeners.MergeMode.REPLACE_DEFAULTS) @ActiveProfiles("test") class WorkflowTest {
 @Autowired Auth auth;@Autowired TaskService tasks;@Autowired Records records;@Autowired Store db;@Autowired Policy policy;@Autowired Writes writes;@Autowired PlatformTransactionManager manager;@Autowired KpiController kpi;@Autowired Jsons json;
 final Policy.Actor leader=new Policy.Actor(2,"COMPANY_LEADER",1,null,2),host=new Policy.Actor(3,"DEPT_HEAD",1,3,3),employee=new Policy.Actor(4,"EMPLOYEE",1,3,4),finance=new Policy.Actor(5,"DEPT_HEAD",1,4,5),other=new Policy.Actor(6,"DEPT_HEAD",2,5,6),admin=new Policy.Actor(1,"ADMIN",1,null,1);
 <T>T tx(java.util.function.Supplier<T> work){return new TransactionTemplate(manager).execute(s->work.get());}
 Map<String,Object> create(){return tx(()->tasks.create(leader,map("title","集成测试任务","content","合成数据，验证生命周期","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(4,5),"priority","NORMAL","deadline",Instant.now().plus(Duration.ofDays(2)).toString())));}
 long id(Map<String,Object>m){return Jsons.number(m.get("id"));}
 Map<String,Object> sub(long task,int dept){return records.children(task,"SUB_TASK").stream().filter(s->Jsons.integer(s.get("deptId"))==dept).findFirst().orElseThrow();}
 void receive(Policy.Actor a,long task,int dept){tx(()->tasks.subAction(a,id(sub(task,dept)),"receive",Map.of()));}
 void submit(Policy.Actor a,long task,int dept){var s=sub(task,dept);tx(()->tasks.subAction(a,id(s),"submit",map("summary","成果版本","version",s.get("version"))));}
 @Test void organizationNamesAreIncludedInTaskAndIdentity(){var task=create();var detail=tasks.detail(leader,id(task));assertThat(detail.get("companyName")).isEqualTo(records.get(1).get("name"));assertThat(detail.get("hostDeptName")).isEqualTo(records.get(3).get("name"));var q=new MockHttpServletRequest();q.getSession().setAttribute("uid",3L);q.getSession().setAttribute("scopeId",3L);var me=auth.meData(q);assertThat(me.get("companyName")).isEqualTo(records.get(1).get("name"));assertThat(me.get("deptName")).isEqualTo(records.get(3).get("name"));assertThat((List<Map<String,Object>>)me.get("scopes")).first().satisfies(scope->assertThat(scope.get("deptName")).isEqualTo(records.get(3).get("name")));}
 @Test void lifecycleCrossCompanyReworkAndAcceptanceAreTransactional(){var t=create();long task=id(t);assertThat(String.valueOf(t.get("code"))).startsWith("RW-DEMOA-");assertThat(records.children(task,"SUB_TASK")).hasSize(2);assertThatThrownBy(()->policy.task(other,task)).isInstanceOf(ApiException.class);assertThatThrownBy(()->policy.task(employee,task)).isInstanceOf(ApiException.class);tx(()->tasks.taskAction(leader,task,"confirm-assign",Map.of()));var request=records.children(task,"COLLABORATION_REQUEST").getFirst();tx(()->tasks.collaboration(other,id(request),"accept",Map.of()));assertThat(records.children(task,"SUB_TASK")).hasSize(3);receive(host,task,3);receive(finance,task,4);receive(other,task,5);tx(()->tasks.subAction(host,id(sub(task,3)),"assign",map("userIds",List.of(4),"ownerId",4)));assertThat(policy.task(employee,task)).isNotNull();submit(employee,task,3);submit(finance,task,4);assertThatThrownBy(()->tx(()->tasks.taskAction(host,task,"summarize",map("version",records.get(task).get("version"))))).isInstanceOf(ApiException.class);submit(other,task,5);tx(()->tasks.taskAction(host,task,"summarize",map("version",records.get(task).get("version"))));tx(()->tasks.taskAction(leader,task,"reject",map("deptIds",List.of(4),"reason","请补全协作成果","version",records.get(task).get("version"))));assertThat(records.get(task).get("status")).isEqualTo("REWORK");assertThat(sub(task,3).get("status")).isEqualTo("REWORK");assertThat(sub(task,4).get("rejectCount")).isEqualTo(1);assertThat(sub(task,3).get("rejectCount")).isEqualTo(0);submit(employee,task,3);submit(finance,task,4);tx(()->tasks.taskAction(host,task,"summarize",map("version",records.get(task).get("version"))));tx(()->tasks.taskAction(leader,task,"accept",map("version",records.get(task).get("version"))));assertThat(records.get(task).get("status")).isEqualTo("COMPLETED");assertThat(records.children(task,"RESULT_VERSION")).hasSize(5);assertThat(sub(task,3).get("status")).isEqualTo("ACCEPTED");assertThatThrownBy(()->tx(()->tasks.subAction(employee,id(sub(task,3)),"withdraw",map("version",sub(task,3).get("version"),"reason","不可撤回")))).isInstanceOf(ApiException.class);}
 @Test void concurrentVersionedWritesOnlyOneWins()throws Exception{var task=create();long id=id(task);tx(()->tasks.taskAction(leader,id,"confirm-assign",Map.of()));int version=Jsons.integer(records.get(id).get("version"));try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);List<Future<Boolean>> f=new ArrayList<>();for(int i=0;i<2;i++)f.add(pool.submit(()->{start.await();try{tx(()->tasks.taskAction(leader,id,"deadline",map("version",version,"reason","并发修改测试","deadline",Instant.now().plus(Duration.ofDays(4)).toString())));return true;}catch(ApiException e){assertThat(e.status).isEqualTo(409);return false;}}));start.countDown();assertThat(f.get(0).get(10,TimeUnit.SECONDS)^f.get(1).get(10,TimeUnit.SECONDS)).isTrue();}}
 @Test void idempotentReplayDoesNotDuplicateTaskOrOutbox(){var q=new MockHttpServletRequest("POST","/api/v1/tasks");q.getSession().setAttribute("uid",2L);q.getSession().setAttribute("scopeId",2L);q.addHeader("Idempotency-Key",UUID.randomUUID().toString());var body=map("title","幂等任务","content","重复创建应相同","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline",Instant.now().plus(Duration.ofDays(2)).toString());Object first=writes.run(q,body,()->tasks.create(leader,body));int count=db.tasks(1,null).size();Object second=writes.run(q,body,()->{throw new AssertionError("replay must not execute");});assertThat(json.write(first)).isEqualTo(json.write(second));assertThat(db.tasks(1,null)).hasSize(count);assertThatThrownBy(()->writes.run(q,Map.of("different",true),()->null)).isInstanceOf(ApiException.class);}
 @Test void kpiSnapshotIsImmutableAndZeroDenominatorIsNotScored(){var template=records.list("KPI_TEMPLATE",null,null).getFirst();var run=(Map<String,Object>)tx(()->kpi.run(admin,map("companyId",1,"period","2025-01","templateId",template.get("id"),"simulation",false)));long runId=id(run);var scores=records.list("KPI_SCORE",1,null).stream().filter(s->Jsons.number(s.get("runId"))==runId).toList();assertThat(scores).isNotEmpty().allSatisfy(s->assertThat(s.get("rawScore")).isNull());String snapshot=String.valueOf(run.get("inputSnapshot"));create();assertThat(records.get(runId).get("inputSnapshot")).isEqualTo(snapshot);var same=(Map<String,Object>)tx(()->kpi.run(admin,map("companyId",1,"period","2025-01","templateId",template.get("id"),"simulation",false)));assertThat(id(same)).isEqualTo(runId);}

 @Test void withdrawalBeforeAcceptanceInvalidatesHostSummary(){var task=tx(()->tasks.create(leader,map("title","验收前撤回","content","历史版本应保留","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(),"deadline",Instant.now().plusSeconds(3600).toString())));long id=id(task);tx(()->tasks.taskAction(leader,id,"confirm-assign",Map.of()));receive(host,id,3);submit(host,id,3);tx(()->tasks.taskAction(host,id,"summarize",map("version",records.get(id).get("version"))));var sub=sub(id,3);tx(()->tasks.subAction(host,id(sub),"withdraw",map("version",sub.get("version"),"reason","修订成果")));assertThat(records.get(id).get("status")).isEqualTo("IN_PROGRESS");assertThat(records.get(id).get("summarizedAt")).isNull();assertThat(records.children(id,"RESULT_VERSION")).hasSize(1);assertThat(sub(id,3).get("submittedAt")).isNull();}
 @Test void gapAcceptanceDoesNotInventMissingSubmission(){var task=tx(()->tasks.create(leader,map("title","缺项验收","content","不能虚增完成指标","companyId",1,"hostDeptId",3,"collaboratorDeptIds",List.of(4),"deadline",Instant.now().plusSeconds(3600).toString())));long id=id(task);tx(()->tasks.taskAction(leader,id,"confirm-assign",Map.of()));receive(host,id,3);receive(finance,id,4);submit(host,id,3);tx(()->tasks.taskAction(host,id,"summarize",map("version",records.get(id).get("version"),"allowGap",true,"reason","领导确认缺项")));tx(()->tasks.taskAction(leader,id,"accept",map("version",records.get(id).get("version"))));assertThat(sub(id,3).get("status")).isEqualTo("ACCEPTED");assertThat(sub(id,4).get("status")).isEqualTo("IN_PROGRESS");assertThat(sub(id,4).get("submittedAt")).isNull();assertThat(sub(id,4).get("gapClosed")).isEqualTo(true);}
}
